export type TermMessage_Serialize = 
/**  Output bytes, base64 encoded (terminal output is not always UTF-8). */
{ kind: "data"; b64: string } | { kind: "status"; state: TermState; attempt: number; message: string | null } | { kind: "exit"; code: number | null };

/**
 *  Result of opening an SSH terminal. `needsUser` carries the prompt the UI
 *  must show (host key, password, passphrase) before calling again.
 */
export type TermOpen = { kind: "opened"; id: number } | { kind: "needsUser"; error: ConnectError };

export type TermState = "connecting" | "connected" | "reconnecting" | 
/**  Gave up or needs the user (e.g. host key changed). Can be retried. */
"disconnected";

export type TextFile = TextFile_Serialize | TextFile_Deserialize;

export type TextFile_Deserialize = {
	/**  Resolved path (symlinks followed), which is what gets saved. */
	path: string,
	content: string,
	stat: Entry_Deserialize,
};

export type TextFile_Serialize = {
	/**  Resolved path (symlinks followed), which is what gets saved. */
	path: string,
	content: string,
	stat: Entry_Serialize,
};
